    if (next < 0) return { clarify: 'That would make the stock negative (' + qty + ' ' + (action.delta < 0 ? '−' : '+') + ' ' + Math.abs(action.delta) + '). Send the exact quantity instead, e.g. "set stock ... to 0".' };
    return { write: { stock_quantity: next } };
  }
